/**
 * In-portal classroom: keeps BigBlueButton live classes and recordings inside a Hikmah page.
 *
 * @module     theme_hikmah/classroom
 * @copyright  2026 Hikmah Institute
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

const VIEWPATH = /\/mod\/bigbluebuttonbn\/bbb_view\.php$/;
const PASSTHROUGH = ['id', 'bn', 'rid', 'rtype', 'group'];

/**
 * Sends "Join session" and recording links to the classroom page instead of a new window.
 *
 * The listener runs in the capture phase so it acts before the BigBlueButton activity's own
 * click handlers. Modified clicks (Ctrl, middle button…) keep the standard new-window behaviour.
 *
 * @param {String} classroomUrl address of the classroom page
 */
export const intercept = (classroomUrl) => {
    document.addEventListener('click', (e) => {
        if (e.button !== 0 || e.ctrlKey || e.metaKey || e.shiftKey || e.altKey) {
            return;
        }
        const link = e.target.closest ? e.target.closest('a[data-action="join"], a[data-action="play"]') : null;
        if (!link || !link.href) {
            return;
        }
        let source;
        try {
            source = new URL(link.href, window.location.href);
        } catch (error) {
            return;
        }
        const action = source.searchParams.get('action');
        if (source.origin !== window.location.origin || !VIEWPATH.test(source.pathname) ||
                (action !== 'join' && action !== 'play')) {
            return;
        }
        const target = new URL(classroomUrl, window.location.href);
        PASSTHROUGH.forEach((name) => {
            const value = source.searchParams.get(name);
            if (value !== null && value !== '') {
                target.searchParams.set(name, value);
            }
        });
        if (action === 'play' && !target.searchParams.get('rid')) {
            return;
        }
        e.preventDefault();
        e.stopImmediatePropagation();
        window.location.assign(target.toString());
    }, true);
};

/**
 * Runs the classroom page: loads the class into the frame and follows what happens to it.
 */
export const init = () => {
    const root = document.querySelector('[data-hk-classroom]');
    if (!root || root.dataset.hkReady) {
        return;
    }
    root.dataset.hkReady = '1';

    const frame = root.querySelector('iframe');
    const stage = root.querySelector('[data-hk-stage]');
    const src = frame.getAttribute('data-src');
    const isRecording = root.hasAttribute('data-recording');
    let leaving = false;

    const setState = (state) => root.setAttribute('data-state', state);
    const state = () => root.getAttribute('data-state');
    const load = () => {
        reachedClass = false;
        setState('loading');
        frame.src = src;
    };
    const unload = () => {
        frame.src = 'about:blank';
    };

    // While the class runs on the BigBlueButton server the frame is on another site and cannot
    // be read. Once it can be read again it has come back to this site: after the class was
    // running, that means the class was left or ended (BigBlueButton sends people to Moodle's
    // logout page, which may redirect on to the course or dashboard). Only a return before the
    // class ever opened is an error.
    let reachedClass = false;
    // The class page can take a long time to fire 'load' (it streams media), so also check every
    // second whether the frame has moved to the BigBlueButton server.
    setInterval(() => {
        if (reachedClass || state() !== 'loading' || !frame.getAttribute('src') || frame.getAttribute('src') === 'about:blank') {
            return;
        }
        try {
            // Reading works only while the frame is still on this site.
            void frame.contentWindow.location.href;
        } catch (error) {
            reachedClass = true;
            setState('live');
        }
    }, 1000);
    frame.addEventListener('load', () => {
        let href;
        try {
            href = frame.contentWindow.location.href;
        } catch (error) {
            reachedClass = true;
            setState('live');
            return;
        }
        if (!href || href === 'about:blank') {
            return;
        }
        if (reachedClass || href.indexOf('action=logout') !== -1) {
            unload();
            setState('ended');
            return;
        }
        setState('error');
    });

    root.addEventListener('click', (e) => {
        const target = e.target.closest ? e.target.closest('[data-hk-rejoin], [data-hk-newtab], [data-hk-leave], ' +
            '[data-hk-fullscreen]') : null;
        if (!target) {
            return;
        }
        if (target.hasAttribute('data-hk-rejoin')) {
            load();
        } else if (target.hasAttribute('data-hk-newtab')) {
            // The link opens the class in its own tab; drop this copy so the learner is not in twice.
            unload();
            setState('moved');
        } else if (target.hasAttribute('data-hk-leave')) {
            leaving = true;
        } else if (document.fullscreenElement) {
            document.exitFullscreen();
        } else {
            stage.requestFullscreen().catch(() => null);
        }
    });

    const fullscreen = root.querySelector('[data-hk-fullscreen]');
    if (fullscreen && stage.requestFullscreen && document.fullscreenEnabled) {
        fullscreen.hidden = false;
    }

    // Ask before a stray Back or reload drops the learner out of a running class.
    window.addEventListener('beforeunload', (e) => {
        if (!leaving && !isRecording && state() === 'live') {
            e.preventDefault();
            e.returnValue = '';
        }
    });

    load();
};
